// Content with portions generated by generative AI platform
package org.eclipse.kura.core.configuration;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.File;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

import org.eclipse.kura.core.testutil.TestUtil;
import org.eclipse.kura.system.SystemService;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SnapshotGarbageCollectionTest {

    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    private File snapshotsDir;
    private SystemService systemService;
    private ConfigurationServiceImpl configurationService;

    @Before
    public void setUp() throws IOException {
        this.snapshotsDir = this.temporaryFolder.newFolder("snapshots");
    }

    @After
    public void tearDown() {
        this.configurationService = null;
    }

    @Test
    public void snapshotsAreKeptWhenBelowConfiguredCount() throws Throwable {
        givenSnapshots(0, 121, 122, 123);
        givenConfiguredSnapshotsCount(10);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(0, 121, 122, 123);
    }

    @Test
    public void oldestSnapshotsAreDeletedWhenAboveConfiguredCount() throws Throwable {
        givenSnapshots(0, 121, 122, 123, 124, 125);
        givenConfiguredSnapshotsCount(4);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(0, 123, 124, 125);
    }

    @Test
    public void largeConfiguredCountIsNotCappedToTheMinimum() throws Throwable {
        givenSnapshots(0, 121, 122, 123, 124, 125, 126, 127);
        givenConfiguredSnapshotsCount(10);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(0, 121, 122, 123, 124, 125, 126, 127);
    }

    @Test
    public void configuredCountOfOneIsRaisedToTwo() throws Throwable {
        givenSnapshots(0, 121, 122, 123);
        givenConfiguredSnapshotsCount(1);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(0, 123);
    }

    @Test
    public void configuredCountOfZeroIsRaisedToTwo() throws Throwable {
        givenSnapshots(121, 122, 123);
        givenConfiguredSnapshotsCount(0);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(122, 123);
    }

    @Test
    public void negativeConfiguredCountIsRaisedToTwo() throws Throwable {
        givenSnapshots(121, 122, 123);
        givenConfiguredSnapshotsCount(-1);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(122, 123);
    }

    @Test
    public void snapshotZeroIsNeverDeleted() throws Throwable {
        givenSnapshots(0, 121, 122, 123, 124);
        givenConfiguredSnapshotsCount(2);

        whenGarbageCollectionRuns();

        thenSnapshotExists(0);
        thenRemainingSnapshotsAre(0, 124);
    }

    @Test
    public void nothingIsDeletedWhenOnlyTheMinimumNumberOfSnapshotsExists() throws Throwable {
        givenSnapshots(0, 121);
        givenConfiguredSnapshotsCount(0);

        whenGarbageCollectionRuns();

        thenRemainingSnapshotsAre(0, 121);
    }

    private void givenSnapshots(final long... ids) throws IOException {
        for (final long id : ids) {
            assertTrue(new File(this.snapshotsDir, "snapshot_" + id + ".xml").createNewFile());
        }
    }

    private void givenConfiguredSnapshotsCount(final int count) {
        final File dir = this.snapshotsDir;

        this.systemService = mock(SystemService.class);
        when(this.systemService.getKuraSnapshotsCount()).thenReturn(count);

        this.configurationService = new ConfigurationServiceImpl() {

            @Override
            String getSnapshotsDirectory() {
                return dir.getAbsolutePath();
            }
        };
        this.configurationService.setSystemService(this.systemService);
    }

    private void whenGarbageCollectionRuns() throws Throwable {
        TestUtil.invokePrivate(this.configurationService, "garbageCollectionOldSnapshots");
    }

    private void thenRemainingSnapshotsAre(final long... expectedIds) {
        final Set<String> expected = new HashSet<>();
        for (final long id : expectedIds) {
            expected.add("snapshot_" + id + ".xml");
        }

        final String[] actualNames = this.snapshotsDir.list();
        final Set<String> actual = new HashSet<>(Arrays.asList(actualNames == null ? new String[0] : actualNames));

        assertEquals(expected, actual);
    }

    private void thenSnapshotExists(final long id) {
        assertTrue("snapshot_" + id + ".xml should exist", new File(this.snapshotsDir, "snapshot_" + id + ".xml").exists());
        assertFalse("snapshot directory should not be empty", this.snapshotsDir.list().length == 0);
    }

}
